svg.script:
(function () {
  "use strict";

  var script = document.currentScript;
  var svg = script ? script.ownerSVGElement : null;

  if (!svg) {
    return;
  }

  var links = svg.querySelectorAll("a[data-title]");
  var tooltip = svg.getElementById("tooltip");
  var tooltipBox = svg.getElementById("tooltip-box");
  var tooltipText = svg.getElementById("tooltip-text");

  if (!tooltip || !tooltipBox || !tooltipText) {
    return;
  }

  function clientToSvg(clientX, clientY) {
    var point = svg.createSVGPoint();
    var matrix = svg.getScreenCTM();

    point.x = clientX;
    point.y = clientY;

    if (!matrix) {
      return {
        x: clientX,
        y: clientY
      };
    }

    return point.matrixTransform(matrix.inverse());
  }

  function placeTooltip(x, y, title) {
    var width = Math.max(
      170,
      Math.min(390, title.length * 7.7 + 32)
    );

    var tooltipX = x + 17;
    var tooltipY = y - 62;

    if (tooltipX + width > 1180) {
      tooltipX = x - width - 17;
    }

    if (tooltipX < 20) {
      tooltipX = 20;
    }

    if (tooltipY < 30) {
      tooltipY = y + 24;
    }

    if (tooltipY > 815) {
      tooltipY = 815;
    }

    tooltipText.textContent = title;
    tooltipBox.setAttribute("width", width);

    tooltip.setAttribute(
      "transform",
      "translate(" + tooltipX + " " + tooltipY + ")"
    );

    tooltip.classList.add("visible");
    tooltip.setAttribute("aria-hidden", "false");

    /*
     * Move the tooltip to the end of the SVG paint order so that
     * landscape elements cannot be drawn over it.
     */
    svg.appendChild(tooltip);
  }

  function showPointerTooltip(event, link) {
    var position = clientToSvg(event.clientX, event.clientY);
    var title =
      link.getAttribute("data-title") ||
      "Watershed feature";

    placeTooltip(position.x, position.y, title);
  }

  function showFocusTooltip(link) {
    var title =
      link.getAttribute("data-title") ||
      "Watershed feature";

    try {
      var box = link.getBBox();
      var matrix = link.getCTM();
      var point = svg.createSVGPoint();

      point.x = box.x + box.width / 2;
      point.y = box.y;

      var transformed = matrix
        ? point.matrixTransform(matrix)
        : point;

      placeTooltip(
        transformed.x,
        transformed.y,
        title
      );
    } catch (error) {
      placeTooltip(600, 90, title);
    }
  }

  function hideTooltip() {
    tooltip.classList.remove("visible");
    tooltip.setAttribute("aria-hidden", "true");
  }

  Array.prototype.forEach.call(links, function (link) {
    link.addEventListener("mouseenter", function (event) {
      showPointerTooltip(event, link);
    });

    link.addEventListener("mousemove", function (event) {
      showPointerTooltip(event, link);
    });

    link.addEventListener("mouseleave", hideTooltip);

    link.addEventListener("focus", function () {
      showFocusTooltip(link);
    });

    link.addEventListener("blur", hideTooltip);
    link.addEventListener("click", hideTooltip);
  });

  svg.addEventListener("mouseleave", hideTooltip);
}());
